#!/usr/bin/env python
"""Generate docs/engines/*.md from the engines' own metadata (capabilities, limitations, dependencies) so docs cannot drift from code.
Hand-written parts (interface, errors, extension) live in EXTRA below."""
from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from intelligence.app import Avoenix  # noqa: E402
from intelligence.storage import MemoryBackend  # noqa: E402

EXTRA = {
    "input": ("`InputProcessingEngine.process(raw, channel, metadata) -> InputPacket`", "Empty/oversized/non-text input raises `InputError`; unsupported language raises `UnsupportedLanguageError` (the orchestrator turns both into a user-readable reply).",
              "Add function words to the language-detection profiles in `engines/input/engine.py`; new languages require a new Language Engine adapter (not provided)."),
    "language": ("`LanguageEngine.analyze(InputPacket) -> LanguageResult` (ACR document + confidence + diagnostics)", "Unparseable input yields a low-confidence result with diagnostics, never an exception; internal failures raise `EngineError`.",
                 "Extend the lexicon (`engines/language/en/lexicon.py`: `GRADABLE`, `RELATIONAL_NOUNS`), gazetteer, or register ACR concepts via `representation.concepts.register`."),
    "context": ("`ContextEngine.resolve(doc, state) -> ResolutionReport`, `update(state, doc, user_text=..., system_text=...)`, `new_state(cid)`", "Ambiguous references produce a clarification request rather than a guess.", "Resolution rules are ordered functions in `engines/context/engine.py`; state is serialisable."),
    "memory": ("`MemoryEngine.remember / recall / recent / set_preference / get_preference / forget / prune / inspect`", "Scope violations raise `ScopeError`; missing rows `NotFoundError`; storage failures `StorageError`.", "Add a memory category and its retention rule in `engines/memory/engine.py`; swap the storage `Backend`."),
    "knowledge": ("`KnowledgeEngine.seed / assert_fact / assert_proposition / query / search / retract / restore / list_facts`", "Writing seed-level sources at user level raises `ScopeError`; unknown terms return suggestions instead of guesses.", "Add curated facts to `engines/knowledge/seed.py` (idempotent, deterministic ids); new predicates need a realiser entry in the Response Engine."),
    "reasoning": ("`ReasoningEngine.reason(scope, LanguageResult, conversation_id) -> ReasoningResult`", "A failing strategy is recorded in `strategies_tried` and does not abort other strategies.", "`ReasoningEngine.register(Strategy, first=False)` / `unregister(name)` at runtime; each strategy declares `applies(query)` and `run(query, factbase)`."),
    "learning": ("`LearningEngine.learn_from_message / submit_feedback / apply / revert / approve / reject / history / run_golden`", "Invalid proposals raise `LearningRejected`; a failed read-back verification rolls the change back and reports failure (never claims learning).", "Add whitelisted keys to `PREFERENCE_DOMAIN` / `STRATEGY_DOMAIN` and golden probes to `GOLDEN`."),
    "emotion": ("`EmotionEngine.analyze(LanguageResult) -> EmotionSignal`", "Never raises on text content; neutral with `certainty=0` when no cues exist.", "Extend the lexicon in `engines/emotion/engine.py`."),
    "planning": ("`PlanningEngine.detect_goal / create_goal / add_task / update_task / rank / next_actions / evaluate`", "Cyclic dependencies and infeasible schedules are reported as structured problems.", "Decomposition patterns live in `decompose()`; scheduling functions are pure and replaceable."),
    "personality": ("`PersonalityEngine.observe(scope, LanguageResult)`, `profile(scope, emotion) -> StyleProfile`", "Missing memory yields the base character.", "Adjust base traits and adaptation rules in `engines/personality/engine.py`."),
    "response": ("`ResponseGenerationEngine.generate(plan, style, emotion, state, seed, name, occasion) -> Response`", "Realisation failures fall back to a plain statement of the facts; variation never changes facts.", "Add message realisers `_m_<type>` and weighted `Opt` skeletons; emoji rules in `engines/response/emoji.py`."),
    "evaluation": ("`EvaluationEngine.assess_turn(...)`, `run_suite(cases, respond, ...)`, `latest_runs()`", "A crashing case counts as FAILED, never skipped.", "Add check types in `EvaluationEngine.check`; datasets are plain JSON."),
}

app = Avoenix(MemoryBackend())
out = ROOT / "docs" / "engines"
out.mkdir(parents=True, exist_ok=True)
idx = ["# Engines (v0.0.0)", "", "Generated by `scripts/generate_engine_docs.py` from engine metadata. Status values are the engines' own declarations; see `docs/CAPABILITY_ASSESSMENT.md` for what is verified.", "",
       "| # | Engine | Depends on | Status |", "|---|---|---|---|"]
for i, e in enumerate(app.engines_info(), 1):
    iface, errors, ext = EXTRA[e["key"]]
    md = [f"# {e['name']} (`{e['key']}`) — v{e['version']}", "", f"**Status:** {e['status']}  ", f"**Depends on:** {', '.join(e['depends_on']) or 'none'}", "", e["summary"], "",
          "## Interface", "", iface, "", "## Capabilities", ""] + [f"- {c}" for c in e["capabilities"]] + ["", "## Known limitations", ""] + [f"- {c}" for c in e["limitations"]] + \
         ["", "## Error handling", "", errors, "", "## Extension mechanism", "", ext, "", "## Tests", "", f"See `tests/` (unit, integration, acceptance) and `docs/TESTING.md`. Health: `GET /v1/diagnostics` runs this engine's `self_check()`.", ""]
    (out / f"{i:02d}-{e['key']}.md").write_text("\n".join(md))
    idx.append(f"| {i} | [{e['name']}]({i:02d}-{e['key']}.md) | {', '.join(e['depends_on']) or '—'} | {e['status']} |")
(out / "README.md").write_text("\n".join(idx) + "\n")
print("wrote", len(app.engines_info()), "engine docs")
